using System.Collections.Immutable;

namespace Scion.Core.Tests;

public class CanonicalChangesetSerializerTests
{
    // Golden vectors produced on 2026-10-30 by an independent implementation of the v1 canonical
    // format (Python: struct + hashlib). Any serializer change that moves a byte of this encoding
    // changes every changeset Id and must be a deliberate format-version bump.
    // Generated by /tmp/golden.py (independent Python implementation) - do not edit by hand.
