        + "6535636634656539313838633562363238313863626337306436323738633436616339643836"
        + "646131313035330000000b6c696e6b2f74617267657400020001000000403366646338303731"
        + "6163663734353166663366373130356161393037366664383735656632333065326530663736"
        + "313437616233323435663466643731643332000000076f6c642e747874020001000000403238"
        + "3362623964656566303265363834336162666235333865666131656361373038303162643861"
        + "373031633366393831393165313233343936333339323437000000001b7372632f5363696f6e"
        + "2f436f72652f4368616e67657365742e63730000000100000040626137383136626638663031"
        + "6366656134313431343064653564616532323233623030333631613339363137376139636234"
        + "313066663631663230303135616400000009746f6f6c732f73636e0301010000004032316130"
        + "3237306237663636613165346332353933336631336131653561316262623437353735373830"
        + "3732393330633831383931333166396336616161653101000000406263633462323763376265"
        + "3966616134393635653635386464626165663162346636386664396130353163333838633530"
        + "3034363137643235303864356266350000001d6665617428636f7265293a2063616e6f6e6963"
        + "616c2068617368696e67000000075061747269636b000000127061747269636b40636c756269"
        + "6e732e6465000000006ab13b80";
    private const string GoldenChangesetId = "6cf68f694cbc31f3c0079c0e1b1948dfb5dff41cd82ffc5b398dcd5012937b70";

    private const string BlobAbc = "ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad";
    private const string BlobEmpty = "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855";
    private const string BlobHello = "bfddb69216adb138de5ae585a4849a993fe2a196cd464ac825ec7f90ae217e9b";
    private const string BlobDocs = "b610e54a9e3e2798643e5cf4ee9188c5b62818cbc70d6278c46ac9d86da11053";
    private const string BlobGone = "283bb9deef02e6843abfb538efa1eca70801bd8a701c3f98191e123496339247";
    private const string BlobScript = "21a0270b7f66a1e4c25933f13a1e5a1bbb4757578072930c8189131f9c6aaae1";
    private const string BlobScript2 = "bcc4b27c7be9faa4965e658ddbaef1b4f68fd9a051c388c5004617d2508d5bf5";
    private const string BlobTarget = "3fdc8071acf7451ff3f7105aa9076fd875ef230e2e0f76147ab3245f4fd71d32";

    private static Changeset GoldenChangeset()
    {
        ImmutableArray<string> parents =
        [
            "1111111111111111111111111111111111111111111111111111111111111111",
            "2222222222222222222222222222222222222222222222222222222222222222",
        ];

        // Input order deliberately shuffled; the canonical encoding must sort it.
        ImmutableArray<ChangeEntry> changes =
        [
            new ChangeEntry("tools/scn", BlobScript, BlobScript2, FileContentKind.Executable, ChangeType.Renamed),
            new ChangeEntry("README.md", BlobEmpty, BlobHello, FileContentKind.Regular, ChangeType.Modified),
            new ChangeEntry("old.txt", BlobGone, null, FileContentKind.Regular, ChangeType.Deleted),
            new ChangeEntry("link/target", null, BlobTarget, FileContentKind.Symlink, ChangeType.Added),
            new ChangeEntry("src/Scion/Core/Changeset.cs", null, BlobAbc, FileContentKind.Regular, ChangeType.Added),
            new ChangeEntry("docs/über.md", null, BlobDocs, FileContentKind.Regular, ChangeType.Added),
        ];

        return Changeset.Create(
            parents,
            changes,
            "feat(core): canonical hashing",
            new Author("Patrick", "patrick@clubins.de"),
            1_790_000_000);
    }

    [Fact]
    public void Serialize_GoldenChangeset_ProducesPinnedCanonicalBytes()
    {
        var bytes = CanonicalChangesetSerializer.Serialize(GoldenChangeset());

        Assert.Equal(GoldenCanonicalHex, Convert.ToHexString(bytes).ToLowerInvariant());
    }

    [Fact]
    public void ComputeId_CanonicalBytes_MatchesKnownAnswer()
    {
        var canonicalBytes = Convert.FromHexString(GoldenCanonicalHex);

        Assert.Equal(GoldenChangesetId, Sha256.HashHex(canonicalBytes));
    }

    [Fact]
    public void ComputeId_GoldenChangeset_MatchesIndependentImplementation()
    {
        Assert.Equal(GoldenChangesetId, CanonicalChangesetSerializer.ComputeId(GoldenChangeset()));
    }

    [Fact]
    public void Serialize_RepeatedInvocations_ProduceIdenticalBytes()
    {
        var changeset = GoldenChangeset();

        Assert.Equal(CanonicalChangesetSerializer.Serialize(changeset), CanonicalChangesetSerializer.Serialize(changeset));
    }

    [Fact]
    public void Serialize_IgnoresIdFieldAndChangeListOrder()
    {
        var canonical = GoldenChangeset();
        var reshuffled = new Changeset(
            "id-is-not-encoded",
            canonical.Parents,
            canonical.Changes.Reverse().ToImmutableArray(),
            canonical.Message,
            canonical.Author,
            canonical.TimestampUtc);

        Assert.Equal(CanonicalChangesetSerializer.Serialize(canonical), CanonicalChangesetSerializer.Serialize(reshuffled));
    }

    [Fact]
    public void Deserialize_SerializedChangeset_RoundTripsExactly()
    {
        var original = GoldenChangeset();

        var roundTripped = CanonicalChangesetSerializer.Deserialize(CanonicalChangesetSerializer.Serialize(original));

        Assert.Equal(original, roundTripped);
        Assert.Equal(CanonicalChangesetSerializer.Serialize(original), CanonicalChangesetSerializer.Serialize(roundTripped));
    }

    [Fact]
    public void Deserialize_RootEncoding_ProducesEnumerableParentsAndChanges()
    {
        // Regression: CreateBuilder().ToImmutable() used to hand back a *default* ImmutableArray
        // for zero elements, so foreach over a decoded root's Parents/Changes threw
        // NullReferenceException even though Assert.Empty passed. A decoded root must behave like
        // a constructed one under enumeration.
        var original = Changeset.Create([], [], "root", new Author("name", string.Empty), 0);

        var decoded = CanonicalChangesetSerializer.Deserialize(CanonicalChangesetSerializer.Serialize(original));

        Assert.Equal(original, decoded);
        Assert.False(decoded.Parents.IsDefault, "decoded Parents must be [], not a default ImmutableArray");
        Assert.False(decoded.Changes.IsDefault, "decoded Changes must be [], not a default ImmutableArray");
        foreach (var parent in decoded.Parents)
        {
            Assert.Fail("A root changeset has no parents, yet one was enumerated.");
        }

        foreach (var change in decoded.Changes)
        {
            Assert.Fail("An empty change list was enumerated.");
        }
    }

    [Fact]
    public void Deserialize_MinimalRootEncoding_IsAccepted()
    {
        var changeset = CanonicalChangesetSerializer.Deserialize(MinimalOneChangeEncoding(
            type: (byte)ChangeType.Added,
            kind: (byte)FileContentKind.Regular,
            oldBlobMarker: 0,
            newBlobMarker: 1));

        Assert.Empty(changeset.Parents);
        var change = Assert.Single(changeset.Changes);
        Assert.Equal("abc", change.Path);
        Assert.Equal(ChangeType.Added, change.Type);
        Assert.Equal(FileContentKind.Regular, change.Kind);
        Assert.Null(change.OldBlob);
        Assert.Equal("xy", change.NewBlob);
        Assert.Equal(string.Empty, changeset.Message);
        Assert.Equal("name", changeset.Author.Name);
        Assert.Equal(string.Empty, changeset.Author.Email);
        Assert.Equal(0, changeset.TimestampUtc);
    }

    [Fact]
    public void Deserialize_EveryProperPrefix_IsRejected()
    {
        var canonicalBytes = CanonicalChangesetSerializer.Serialize(GoldenChangeset());

        for (var length = 0; length < canonicalBytes.Length; length++)
        {
            Assert.Throws<InvalidDataException>(() => CanonicalChangesetSerializer.Deserialize(canonicalBytes.AsSpan(0, length)));
        }
    }

    [Fact]
    public void Deserialize_TrailingBytes_AreRejected()
    {
        var canonicalBytes = CanonicalChangesetSerializer.Serialize(GoldenChangeset());
        var withTrailing = new byte[canonicalBytes.Length + 1];
        canonicalBytes.CopyTo(withTrailing, 0);
        withTrailing[^1] = 0xFF;

        Assert.Throws<InvalidDataException>(() => CanonicalChangesetSerializer.Deserialize(withTrailing));
    }

    [Fact]
    public void Deserialize_UnknownFormatVersion_IsRejected()
    {
        Assert.Throws<InvalidDataException>(() => CanonicalChangesetSerializer.Deserialize([0x02, 0x00, 0x00, 0x00, 0x00]));
    }

    [Fact]
    public void Deserialize_UnknownChangeType_IsRejected()
    {
        Assert.Throws<InvalidDataException>(() => CanonicalChangesetSerializer.Deserialize(MinimalOneChangeEncoding(
            type: 0x04, kind: 0x00, oldBlobMarker: 0, newBlobMarker: 1)));
    }

    [Fact]
    public void Deserialize_UnknownFileContentKind_IsRejected()
    {
        Assert.Throws<InvalidDataException>(() => CanonicalChangesetSerializer.Deserialize(MinimalOneChangeEncoding(
            type: 0x00, kind: 0x03, oldBlobMarker: 0, newBlobMarker: 1)));
    }

    [Fact]
    public void Deserialize_InvalidOptionalStringMarker_IsRejected()
    {
        Assert.Throws<InvalidDataException>(() => CanonicalChangesetSerializer.Deserialize(MinimalOneChangeEncoding(
            type: 0x00, kind: 0x00, oldBlobMarker: 2, newBlobMarker: 1)));
    }

    private static byte[] MinimalOneChangeEncoding(byte type, byte kind, byte oldBlobMarker, byte newBlobMarker)
    {
        return new byte[]
        {
            0x01,                                                          // format version
            0x00, 0x00, 0x00, 0x00,                                        // no parents (root)
            0x00, 0x00, 0x00, 0x01,                                        // one change
            0x00, 0x00, 0x00, 0x03, (byte)'a', (byte)'b', (byte)'c',       // path "abc"
            type,
            kind,
            oldBlobMarker,
            newBlobMarker, 0x00, 0x00, 0x00, 0x02, (byte)'x', (byte)'y',   // new blob "xy"
            0x00, 0x00, 0x00, 0x00,                                        // empty message
            0x00, 0x00, 0x00, 0x04, (byte)'n', (byte)'a', (byte)'m', (byte)'e',  // author name "name"
            0x00, 0x00, 0x00, 0x00,                                        // author email ""
            0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,                // timestamp 0
        };
    }
}
